ct={}
i=0
for a in bases:
  for b in bases:
    for c in bases:
      ct[a+b+c]=aas[i]; i+=1

def allorfs(s,minaa=40):
    res=[]
    for f in range(3):
        i=f
        cur=None
        while i+3<=len(s):
            aa=ct[s[i:i+3]]
            if aa=='*':
                if cur is not None:
                    st,seqp=cur
                    if len(seqp)>=minaa: res.append((f+1,st,i,seqp))
                cur=None
            else:
                if cur is None: cur=[i,'']
                cur[1]+=aa
            i+=3
        if cur is not None and len(cur[1])>=minaa:
            res.append((f+1,cur[0],len(s),cur[1]))
    return res

