seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
comp=str.maketrans('ACGT','TGCA')
rc=seq.translate(comp)[::-1]
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
ct={}
i=0
for a in bases:
  for b in bases:
    for c in bases:
      ct[a+b+c]=aas[i]; i+=1

def atg_orfs(s,minaa=30):
    L=len(s); out=[]
    for f in range(3):
        for i in range(f,L-2,3):
            if s[i:i+3]!='ATG': continue
            j=i; p=''
            while j+3<=L and ct[s[j:j+3]]!='*':
                p+=ct[s[j:j+3]]; j+=3
            if len(p)>=minaa:
                out.append((f+1,i,j,len(p),p))
    # keep only those not contained in another (keep all for now)
    return out

print("FORWARD ATG ORFs >=30aa")
for f,s,e,l,p in atg_orfs(seq,30):
    print(f'+',s+1,e,l,p)
print()
print("REVERSE ATG ORFs >=30aa")
for f,s,e,l,p in atg_orfs(rc,30):
    L=len(seq)
    print(f'-',L-e+1,L-s,l,p)
